class _PaddonWipCard extends StatelessWidget {
  const _PaddonWipCard({
    super.key,
    required this.slot,
    required this.batch,
    this.selected = false,
    this.onSelect,
    required this.selectionIcon,
    this.onLongPress,
    this.onRemove,
  });

  final M3SegmentVerticalSlot slot;
  final AdminProgressBatch batch;
  final bool selected;
  final VoidCallback? onSelect;
  final IconData selectionIcon;
  final VoidCallback? onLongPress;
  final VoidCallback? onRemove;

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    final theme = Theme.of(context);
    final orderSummary = AparatchiPaddonDisplay.orderSummary(batch);
    final qr = batch.qrPayload.trim();
    final epc = qr.isNotEmpty ? qr : '—';
    final lengthM = batch.finishedGoodsMeter;
    final hasLength = lengthM != null && lengthM.isFinite && lengthM > 0 ||
        (batch.uom.trim().toLowerCase() == 'm' &&
            batch.producedQty.isFinite &&
            batch.producedQty > 0);
    final lengthText = !hasLength
        ? ''
        : formatQuantityWithUnit(
            lengthM != null && lengthM.isFinite && lengthM > 0
                ? lengthM
                : batch.producedQty,
            'm',
            trimTrailingZeros: true,
          );
    final card = M3SegmentFilledSurface(
      slot: slot,
      cornerRadius: M3SegmentedListGeometry.cornerRadiusForSlot(slot),
      onTap: onSelect,
      onLongPress: onLongPress,
      child: ConstrainedBox(
        constraints: const BoxConstraints(minHeight: 64),
        child: Padding(
          padding: const EdgeInsets.fromLTRB(14, 12, 14, 12),
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              Expanded(
                child: Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    UrduAwareText(
                      '${context.l10n.productionText('worker.paddon.order')}: $orderSummary',
                      style: theme.textTheme.bodyMedium?.copyWith(
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                    UrduAwareText(
                      lengthText.isEmpty
                          ? 'EPC: $epc'
                          : 'EPC: $epc • $lengthText',
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                      style: theme.textTheme.bodySmall?.copyWith(
                        color: scheme.onSurfaceVariant,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                  ],
                ),
              ),
              if (onSelect != null) ...[
                const SizedBox(width: 10),
                Icon(
                  selected ? Icons.check_circle_rounded : selectionIcon,
                  size: 28,
                  color: selected ? scheme.primary : scheme.onSurfaceVariant,
                ),
              ],
            ],
          ),
        ),
      ),
    );
    if (onRemove == null) return card;
    return _PaddonSwipeRemoveCard(
      actionKey: ValueKey('paddon-remove-wip-${batch.batchId}'),
      borderRadius: M3SegmentedListGeometry.borderRadius(
        slot,
        M3SegmentedListGeometry.cornerRadiusForSlot(slot),
      ),
      label: context.l10n.productionText('worker.paddon.remove'),
      onRemove: onRemove!,
      child: card,
    );
  }
}

